 21	type persistentRefBuilder func() (newHash, expectedHash plumbing.Hash, err error)
 22	
 23	func repositoryDirs(ctx context.Context, repo *git.Repository) (worktreeRoot, commonDir string, err error) {
 24		wt, err := repo.Worktree()
 25		if err != nil {
 26			return "", "", fmt.Errorf("open worktree: %w", err)
 27		}
 28		worktreeRoot = wt.Filesystem().Root()
 29		if worktreeRoot == "" {
 30			return "", "", errors.New("repository worktree filesystem has no root path")
 31		}
 32		commonDir, err = resolveGitCommonDir(ctx, repo)
 33		if err != nil {
 34			return "", "", err
 35		}
 36		return worktreeRoot, commonDir, nil
 37	}
 38	
 39	// casUpdateRef atomically updates refName through native Git's lock protocol.
 40	// Pass ZeroHash as expectedHash to require that the ref does not exist.
 41	func casUpdateRef(ctx context.Context, repoRoot string, refName plumbing.ReferenceName, newHash, expectedHash plumbing.Hash) error {
 42		newValue := newHash.String()
 43		oldValue := strings.Repeat("0", newHash.HexSize())
 44		if expectedHash != plumbing.ZeroHash {
 45			oldValue = expectedHash.String()
 46		}
 47	
 48		cmd := exec.CommandContext(ctx, "git", "update-ref", refName.String(), newValue, oldValue)
 49		cmd.Dir = repoRoot
 50		cmd.Env = append(os.Environ(), "LC_ALL=C", "LANG=C")
 51		output, err := cmd.CombinedOutput()
 52		if err == nil {
 53			return nil
 54		}
 55	
 56		if isPersistentRefBusy(output) {
 57			return ErrShadowRefBusy
 58		}
 59		return fmt.Errorf("git update-ref %s: %s: %w", refName, strings.TrimSpace(string(output)), err)
 60	}
 61	
 62	func isPersistentRefBusy(stderr []byte) bool {
 63		if gitrepo.IsRefCASConflict(stderr) {
 64			return true
 65		}
 66		msg := strings.ToLower(string(stderr))
 67		return strings.Contains(msg, ".lock") && strings.Contains(msg, "file exists")
 68	}
 69	
 70	func persistentRefLockPath(commonDir string, refName plumbing.ReferenceName) (string, error) {
 71		lockDir := filepath.Join(commonDir, "entire-persistent-ref-locks")
 72		if err := os.MkdirAll(lockDir, 0o750); err != nil {
 73			return "", fmt.Errorf("create persistent ref lock directory: %w", err)
 74		}
 75		safe := strings.NewReplacer("/", "_", "\\", "_", ":", "_").Replace(refName.String())
 76		return filepath.Join(lockDir, safe+".lock"), nil
 77	}
 78	
 79	func withPersistentRefFlock(ctx context.Context, commonDir string, refName plumbing.ReferenceName, fn func() error) error {
 80		path, err := persistentRefLockPath(commonDir, refName)
 81		if err != nil {
 82			return err
 83		}
 84		release, err := flock.AcquireContext(ctx, path)
 85		if err != nil {
 86			return fmt.Errorf("acquire persistent ref flock %s: %w", refName, err)
 87		}
 88		defer release()
 89		return fn()
 90	}
 91	
 92	func withLockedPersistentRef(
 93		ctx context.Context,
 94		repo *git.Repository,
 95		refName plumbing.ReferenceName,
 96		fn func(repoRoot, commonDir string) error,
 97	) error {
 98		repoRoot, commonDir, err := repositoryDirs(ctx, repo)
 99		if err != nil {
100			return fmt.Errorf("resolve repository directories: %w", err)
101		}
102		return withPersistentRefFlock(ctx, commonDir, refName, func() error {
103			return fn(repoRoot, commonDir)
104		})
105	}
