107	// CASPersistentRef serializes with Entire's persistent ref writers and updates
108	// refName through native Git's cross-process compare-and-swap protocol.
109	func CASPersistentRef(
110		ctx context.Context,
111		repo *git.Repository,
112		refName plumbing.ReferenceName,
113		newHash, expectedHash plumbing.Hash,
114	) error {
115		return withLockedPersistentRef(ctx, repo, refName, func(repoRoot, _ string) error {
116			return casUpdateRef(ctx, repoRoot, refName, newHash, expectedHash)
117		})
118	}
