120	// updatePersistentRef serializes Entire writers for one ref and retains a CAS
121	// retry for native Git or other external writers. build runs again after every
122	// conflict, so each retry reconstructs its tree and commit from the fresh tip.
123	func updatePersistentRef(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, build persistentRefBuilder) error {
124		return withLockedPersistentRef(ctx, repo, refName, func(repoRoot, commonDir string) error {
125			for attempt := range shadowRefMaxRetries {
126				newHash, expectedHash, buildErr := build()
