149				slog.String("ref", refName.String()),
150				slog.Int("retries", shadowRefMaxRetries),
151			)
152			return fmt.Errorf("failed to update persistent ref %s after %d CAS retries: %w", refName, shadowRefMaxRetries, ErrShadowRefBusy)
153		})
