   336		rawCap := scaleBatchLimit(resolveBatchLimit(), rawByteCapMultiplier)
   337		var rawBytesSoFar int
   338		for _, c := range unpushed {
   339			pc := pendingCommit{commit: c}
   340			if !trailers.HasOPFApplied(c.Message) {
   341				tree, err := repo.TreeObject(c.TreeHash)
   342				if err != nil {
   343					return plumbing.ZeroHash, fmt.Errorf("load tree for %s: %w", c.Hash.String()[:7], err)
   344				}
   345				pc.startIdx = len(globalBlobs)
   346				// Whole-tree redaction: each v1 commit tree is cumulative, so the
   347				// newest commit can still carry older shards that were regex-only
   348				// before this rewrite. Redacting the whole tree for every unapplied
   349				// commit keeps the final rewritten tip from reintroducing an
   350				// un-OPF-redacted older shard. collect and apply walk the tree the
   351				// same way so the cached keys line up.
   352				if err := collectTreeBlobs(repo, tree, "", &pc.blobs, &pc.paths); err != nil {
   353					return plumbing.ZeroHash, fmt.Errorf("collect blobs %s: %w", c.Hash.String()[:7], err)
   354				}
   355				for _, b := range pc.blobs {
   356					rawBytesSoFar += len(b.Content)
   357				}
   358				if rawBytesSoFar > rawCap {
   359					return plumbing.ZeroHash, &OPFRawBytesTooLargeError{RawBytes: rawBytesSoFar, Limit: rawCap}
   360				}
   361				globalBlobs = append(globalBlobs, pc.blobs...)
   362			}
   363			pendings = append(pendings, pc)
   364		}
   365	
   366		// Pass 2: enforce the leaf-byte cap, then make exactly ONE OPF
   367		// shell-out for the whole push. The cap runs before the shell-out
   368		// so a too-large push fails fast with a clear remediation message.
   369		var globalRedacted [][]byte
   370		if len(globalBlobs) > 0 {
   371			leafBytes := redact.SumProseLeafBytes(globalBlobs)
   372			if limit := resolveBatchLimit(); leafBytes > limit {
   373				return plumbing.ZeroHash, &OPFBatchTooLargeError{LeafBytes: leafBytes, Limit: limit}
   374			}
   375			globalRedacted, err = redact.BatchBytesWithPrivacyFilter(ctx, globalBlobs)
   376			if err != nil {
   377				// Converge with the up-front gate: the misconfiguration
   378				// sentinel must surface config remediation, not "verify
   379				// your OPF install".
   380				if errors.Is(err, redact.ErrOPFNoEnabledCategories) {
   381					return plumbing.ZeroHash, &OPFNoCategoriesError{}
   382				}
   383				return plumbing.ZeroHash, &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand(), Cause: err}
   384			}
   385		}
   386	
   387		// Pass 3: rebuild each commit. For OPF-applied commits, this is
   388		// just a re-parent (no tree changes). For unapplied commits, the
   389		// per-commit redaction map routes cached bytes by tree path.
   390		parent := remoteTip
   391		for _, pc := range pendings {
   392			var redactedByPath map[string][]byte
   393			if len(pc.blobs) > 0 {
   394				redactedByPath = make(map[string][]byte, len(pc.blobs))
   395				for i, path := range pc.paths {
   396					redactedByPath[path] = globalRedacted[pc.startIdx+i]
   397				}
   398			}
   399			newHash, err := rebuildCheckpointCommit(ctx, repo, pc.commit, parent, redactedByPath)
   400			if err != nil {
   401				return plumbing.ZeroHash, fmt.Errorf("rebuild commit %s: %w", pc.commit.Hash.String()[:7], err)
   402			}
   403			parent = newHash
   404		}
   405	
   406		if err := atomicSetV1Ref(ctx, repo, localTip, parent); err != nil {
   407			return plumbing.ZeroHash, err
   408		}
   409		return parent, nil
   410	}
   411	
   412	func readV1Tip(repo *git.Repository, refName plumbing.ReferenceName) (plumbing.Hash, error) {
   413		ref, err := repo.Reference(refName, true)
   414		if err != nil {
   415			if errors.Is(err, plumbing.ErrReferenceNotFound) {
   416				return plumbing.ZeroHash, nil
