   422	
   423	// opfRewriteFetchTmpRef is the temp ref used to stage the URL-fetched
   424	// remote v1 tip during OPF rewrite. Cleaned up at the end of each
   425	// resolveRemoteV1Tip call so the tracking is invisible to the user.
   426	const opfRewriteFetchTmpRef = FetchTmpRefPrefix + "opf-rewrite-v1"
   427	
   428	// resolveRemoteV1Tip returns the hash of the remote's
   429	// entire/checkpoints/v1 tip.
   430	//
     1	// Pre-push OPF rewrite for the git-refs checkpoint backend, the sibling of
     2	// manual_commit_opf_rewrite.go's entire/checkpoints/v1 rewrite. Both run the
     3	// OPF-augmented redaction once per push; only discovery and ref update differ.
     4	package strategy
     5	
     6	import (
     7		"context"
     8		"errors"
     9		"fmt"
    10		"slices"
    11	
    12		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
    13		"github.com/entireio/cli/cmd/entire/cli/trailers"
    14		"github.com/entireio/cli/redact"
    15		"github.com/go-git/go-git/v6"
    16		"github.com/go-git/go-git/v6/plumbing"
    17		"github.com/go-git/go-git/v6/plumbing/object"
    18	)
    19	
    20	// RewriteQueuedCheckpointRefsWithOPF re-redacts the checkpoint refs awaiting
    21	// push with OPF, rebuilds every un-applied commit on each as a commit carrying
    22	// Entire-OPF-Applied: true, and points the ref at the new tip. Idempotent: a
    23	// ref whose tip already carries the trailer is left byte-identical.
    24	//
    25	// Discovery is the push-discovery queue rather than a local-vs-remote diff: it
    26	// already names exactly the refs this push will carry, so there is no
    27	// merge-base or divergence analysis. Within a ref, pushing it carries its whole
    28	// unpushed ancestry, so the walk covers every commit back to the first one
    29	// already carrying the trailer (unappliedAncestry) — bounded by the same
    30	// resolveBootstrapLimit the v1 path uses.
    31	//
    32	// Caller checks redact.OPFEnabled() and skips this when OPF is off. Returns
    33	// the same error taxonomy as RewriteUnpushedV1WithOPF; the caller fails closed
    34	// by withholding the flush (see prePushCheckpointRefs).
    35	func RewriteQueuedCheckpointRefsWithOPF(ctx context.Context, repo *git.Repository) error {
    36		queue, err := checkpoint.PushQueueForRepo(ctx, repo)
    37		if err != nil {
    38			return fmt.Errorf("resolve push queue: %w", err)
    39		}
    40		// Peek, not Drain: flushCheckpointRefsQueue owns draining and pruning.
    41		queued, err := queue.Peek()
    42		if err != nil {
    43			return fmt.Errorf("peek push queue: %w", err)
    44		}
    45		if len(queued) == 0 {
    46			return nil
    47		}
    48	
    49		// Both up-front fail-closed gates, in the same order as the v1 rewrite, so
    50		// a misconfigured category set surfaces config remediation rather than
    51		// "verify your OPF install".
    52		if redact.OPFMisconfiguredNoCategories() {
    53			return &OPFNoCategoriesError{}
    54		}
    55		if redact.OPFBreakerTripped() {
    56			return &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand()}
    57		}
    58	
    59		// Pass 1: collect every redactable blob from every un-applied commit on every
    60		// queued ref, bounding raw bytes in memory exactly as the v1 collect pass
    61		// does — cumulatively across the whole flush, not per ref.
    62		type pendingCommit struct {
    63			commit *object.Commit
    64			// blobs and paths are parallel; startIdx is this commit's offset into
    65			// the global redacted slice.
    66			blobs    []redact.NamedBlob
    67			paths    []string
    68			startIdx int
    69		}
    70		type pendingRef struct {
    71			ref plumbing.ReferenceName
    72			old plumbing.Hash
    73			// base is the parent the deepest rewritten commit keeps.
    74			base    plumbing.Hash
    75			commits []pendingCommit // ancestor-first
    76		}
    77		var globalBlobs []redact.NamedBlob
    78		pendings := make([]pendingRef, 0, len(queued))
    79		rawCap := scaleBatchLimit(resolveBatchLimit(), rawByteCapMultiplier)
    80		bootstrapLimit := resolveBootstrapLimit()
    81		var rawBytesSoFar int
    82		// Stale entries (refs no longer present locally) are skipped, not pruned:
    83		// the queue belongs to the flush.
    84		existing, _ := partitionLocalRefs(repo, queued)
    85		for _, refName := range existing {
    86			ref, refErr := repo.Reference(refName, true)
    87			if refErr != nil {
    88				if errors.Is(refErr, plumbing.ErrReferenceNotFound) {
    89					continue
    90				}
    91				return fmt.Errorf("resolve checkpoint ref %s: %w", refName, refErr)
    92			}
    93			chain, base, walkErr := unappliedAncestry(repo, ref.Hash())
    94			if walkErr != nil {
    95				return fmt.Errorf("walk ancestry of %s: %w", refName, walkErr)
    96			}
    97			if len(chain) == 0 {
    98				continue
    99			}
   100			if len(chain) > bootstrapLimit {
   101				return &BootstrapTooLargeError{Count: len(chain), Limit: bootstrapLimit}
   102			}
   103			pr := pendingRef{ref: refName, old: ref.Hash(), base: base}
   104			for _, c := range chain {
   105				tree, treeErr := repo.TreeObject(c.TreeHash)
   106				if treeErr != nil {
   107					return fmt.Errorf("load tree for %s: %w", c.Hash.String()[:7], treeErr)
   108				}
   109				pc := pendingCommit{commit: c, startIdx: len(globalBlobs)}
   110				if err := collectTreeBlobs(repo, tree, "", &pc.blobs, &pc.paths); err != nil {
   111					return fmt.Errorf("collect blobs %s: %w", c.Hash.String()[:7], err)
   112				}
   113				for _, b := range pc.blobs {
   114					rawBytesSoFar += len(b.Content)
   115				}
   116				if rawBytesSoFar > rawCap {
   117					return &OPFRawBytesTooLargeError{RawBytes: rawBytesSoFar, Limit: rawCap}
   118				}
   119				globalBlobs = append(globalBlobs, pc.blobs...)
   120				pr.commits = append(pr.commits, pc)
   121			}
   122			pendings = append(pendings, pr)
   123		}
   124		if len(pendings) == 0 {
   125			return nil
   126		}
   127	
   128		// Pass 2: enforce the leaf-byte cap, then make exactly ONE OPF shell-out
   129		// for the whole flush.
   130		var globalRedacted [][]byte
   130				return nil
   131			}
   132		}
   133	
   134		// OPF pre-push rewrite: if OPF is configured, resolve the user's
   135		// decision (env > settings > prompt > non-TTY auto-run), then
   136		// re-redact unpushed v1 commits with OPF (producing the OPF-applied,
   137		// 9-layer pipeline) before pushing. Skipped entirely when OPF is off,
   138		// so the common-case fast path is unchanged.
   139		if redact.OPFEnabled() {
   140			decision, decisionErr := opfPrePushDecision(ctx)
   141			if decisionErr != nil {
   142				logging.Warn(ctx, "OPF pre-push decision failed; aborting push",
   143					slog.String("error", decisionErr.Error()),
   144				)
   145				return decisionErr
   146			}
   147			switch decision {
   148			case OPFAbort:
   149				return errOPFAbortedByUser
   150			case OPFSkip:
   151				// User opted out for this push (or settings/env say
   152				// "never"). Push regex-only (8-layer) content as-is.
   153				logging.Info(ctx, "OPF skipped for this push (user choice or settings)")
   154			case OPFRun:
   155				_, opfSpan := perf.Start(ctx, "opf_pre_push_rewrite")
   156				if repoErr != nil {
   157					opfSpan.RecordError(repoErr)
   158					opfSpan.End()
   159					logging.Warn(ctx, "OPF pre-push: failed to open repo; aborting push",
   160						slog.String("error", repoErr.Error()),
   161					)
   162					return repoErr
   163				}
   164				if _, rewriteErr := RewriteUnpushedV1WithOPF(ctx, repo, ps.pushTarget()); rewriteErr != nil {
   165					opfSpan.RecordError(rewriteErr)
   166					opfSpan.End()
   167					logging.Warn(ctx, "OPF pre-push rewrite failed; aborting push",
   168						slog.String("error", rewriteErr.Error()),
   169					)
   170					return rewriteErr
   171				}
   172				opfSpan.End()
   173			}
   174		}
   175	
   176		if deferAutomaticCheckpointPush {
   177			// Do this only after OPF has had a chance to rewrite v1: the outer
   178			// user push may explicitly include the metadata branch.
   179			logging.Info(ctx, "automatic checkpoint push deferred until the remote has a branch",
   180				slog.String("remote", ps.remote),
   181			)
   182			return nil
   183		}
   184	
   185		// Thread the span's context into the push so the network push and any
   186		// fetch+rebase recovery nest beneath it as child steps in the perf trace.
   187		pushCtx, pushCheckpointsSpan := perf.Start(ctx, "push_checkpoint_refs")
   188		// Capture needs checkpoint data CONFIRMED on this remote, so count what
   189		// landed rather than trusting the absence of an error: every ref that was due
   190		// has to deliver, and at least one has to actually do so. Delivery must come
   191		// from pushRefIfNeeded's delivered return and NOT from err, which is
   192		// fail-soft and nil even when the remote refused the ref.
   193		deliveredCount, anyFailed := 0, false
   194		for _, ref := range refs.Push {
   195			delivered, err := pushRefIfNeeded(pushCtx, ps.pushTarget(), ref)
   196			if err != nil {
   197				pushCheckpointsSpan.RecordError(err)
   198				pushCheckpointsSpan.End()
   199				return err
   200			}
   201			if delivered {
   202				deliveredCount++
   203			} else {
   204				anyFailed = true
   205			}
   206		}
   207		pushCheckpointsSpan.End()
   208	
   209		// Delivered: the election may now follow the push that carried it. A push that
   210		// carried nothing — an empty ref set, or a v1 ref that does not exist locally
   211		// yet — leaves the election alone. It is safe either way (nothing is stranded
   212		// when there was nothing to strand), but capturing would announce a move that
   213		// moved no data, which is the class of claim this whole path exists to stop
   214		// making. The next push that carries a checkpoint captures instead.
   215		if pendingCapture != "" && deliveredCount > 0 && !anyFailed {
   216			commitCapturedSyncRemote(ctx, pendingCapture)
   217		}
   218	
   219		cleanupPushedShadowBranches(ctx)
   220		return nil
   221	}
   222	
   223	// opfPrePushDecision resolves the user's OPF decision for this push (env >
   224	// settings > prompt > non-TTY auto-run). Shared by both checkpoint backends so
   225	// the precedence cannot drift between them.
   226	func opfPrePushDecision(ctx context.Context) (OPFDecision, error) {
   227		cfg, _ := settings.Load(ctx) //nolint:errcheck // Load already failed at hook init; fall back to nil
   228		var opfCfg *settings.OPFSettings
   229		if cfg != nil && cfg.Redaction != nil {
   230			opfCfg = cfg.Redaction.OpenAIPrivacyFilter
   231		}
   232		return resolveOPFDecisionForPrePush(ctx, opfCfg, opfPrePushProgressWriter)
   233	}
   234	
   235	// runOPFForCheckpointRefs resolves the OPF decision and, when it says run,
   236	// rewrites the queued checkpoint refs. It reports whether the flush may
   237	// proceed: false means OPF failed or the user aborted, so the caller withholds
   238	// the checkpoint push and leaves the refs queued.
   239	func runOPFForCheckpointRefs(ctx context.Context, repo *git.Repository) bool {
   240		decision, err := opfPrePushDecision(ctx)
   241		if err != nil {
   242			warnOPFCheckpointRefsWithheld(ctx, err)
   243			return false
   244		}
   245		switch decision {
   246		case OPFAbort:
   247			warnOPFCheckpointRefsWithheld(ctx, errOPFAbortedByUser)
   248			return false
   249		case OPFSkip:
   250			// Explicit opt-out for this push: flush the 8-layer content as-is,
   251			// untagged — same as the v1 path.
   252			logging.Info(ctx, "OPF skipped for this push (user choice or settings)")
   253		case OPFRun:
   254			_, opfSpan := perf.Start(ctx, "opf_pre_push_rewrite_refs")
   255			defer opfSpan.End()
   256			if rewriteErr := RewriteQueuedCheckpointRefsWithOPF(ctx, repo); rewriteErr != nil {
   257				opfSpan.RecordError(rewriteErr)
   258				warnOPFCheckpointRefsWithheld(ctx, rewriteErr)
   259				return false
   260			}
   261		}
   262		return true
   263	}
   264	
   265	// warnOPFCheckpointRefsWithheld reports a withheld flush on both channels: the
   266	// log for diagnosis, and the user's terminal so a silently un-synced checkpoint
   267	// is never the first they hear of it.
   268	func warnOPFCheckpointRefsWithheld(ctx context.Context, err error) {
   269		logging.Warn(ctx, "OPF pre-push failed; skipping checkpoint ref push, refs left queued",
   270			slog.String("error", err.Error()),
   271		)
   272		fmt.Fprintf(stderrWriter,
   273			"[entire] OPF did not run, so checkpoint refs were not pushed and stay queued for your next push: %v\n", err)
   274	}
