   262			return plumbing.ZeroHash, fmt.Errorf("read local v1: %w", err)
   263		}
   264		if localTip.IsZero() {
   265			return plumbing.ZeroHash, nil // no checkpoints yet
   266		}
   267		remoteTip, err := resolveRemoteV1Tip(ctx, repo, target)
   268		if err != nil {
   269			return plumbing.ZeroHash, fmt.Errorf("read remote v1: %w", err)
   270		}
