   272		if !remoteTip.IsZero() {
   273			mergeBase, mbErr := computeMergeBase(repo, localTip, remoteTip)
   274			if mbErr != nil {
   275				return plumbing.ZeroHash, fmt.Errorf("compute merge-base: %w", mbErr)
   276			}
   277			if mergeBase != remoteTip {
   278				return plumbing.ZeroHash, &V1DivergedError{Local: localTip, Remote: remoteTip, MergeBase: mergeBase}
   279			}
   280		}
   281	
   282		unpushed, err := listUnpushedV1Commits(repo, localTip, remoteTip)
   283		if err != nil {
   284			return plumbing.ZeroHash, fmt.Errorf("list unpushed v1 commits: %w", err)
   285		}
