   292			}
   293		}
   294	
   295		// Fail-closed defense: enabled-with-no-categories means the model
   296		// scan can't run at all. The decision resolution in prePush already
   297		// rejects this state before any prompt; this second gate covers
   298		// direct callers and sits before the breaker check so the user gets
   299		// the config-specific remediation rather than OPFRuntimeFailedError's
   300		// "verify your OPF install".
   301		if redact.OPFMisconfiguredNoCategories() {
   302			return plumbing.ZeroHash, &OPFNoCategoriesError{}
   303		}
