   328		pendings := make([]pendingCommit, 0, len(unpushed))
   329		// Bound raw-bytes-in-memory incrementally so a pathological push
   330		// (e.g. 5 GiB of pasted dumps) aborts before exhausting the user's
   331		// shell RAM. The leaf-byte cap downstream is about inference cost;
   332		// this one is about memory ceiling and fires earlier. scaleBatchLimit
   333		// saturates at math.MaxInt so "unlimited" actually means unlimited
   334		// — without saturation, "unlimited" × 100 overflows int and the cap
   335		// trips on every push.
   336		rawCap := scaleBatchLimit(resolveBatchLimit(), rawByteCapMultiplier)
