   384			}
   385		}
   386	
   387		// Pass 3: rebuild each commit. For OPF-applied commits, this is
   388		// just a re-parent (no tree changes). For unapplied commits, the
   389		// per-commit redaction map routes cached bytes by tree path.
   390		parent := remoteTip
